const Y=(t,n="YYYY-MM-DD HH:mm:ss",r="-")=>{if(!t||t==="null"||t==="undefined"||t==="NaN")return r;const e=new Date(t);if(isNaN(e.getTime()))return r;const s=e.getFullYear(),a=String(e.getMonth()+1).padStart(2,"0"),o=String(e.getDate()).padStart(2,"0"),c=String(e.getHours()).padStart(2,"0"),i=String(e.getMinutes()).padStart(2,"0"),g=String(e.getSeconds()).padStart(2,"0");return n.replace("YYYY",s.toString()).replace("MM",a).replace("DD",o).replace("HH",c).replace("mm",i).replace("ss",g)},m=t=>Y(t,"YYYY-MM-DD HH:mm:ss");export{Y as a,m as f};
